using System.Runtime.InteropServices; using WindTree.Models; namespace WindTree.Services;
public sealed record PolicyResult(bool Success,string Message);
public sealed class WfpFilteringService{
 public bool IsElevated=>new System.Security.Principal.WindowsPrincipal(System.Security.Principal.WindowsIdentity.GetCurrent()).IsInRole(System.Security.Principal.WindowsBuiltInRole.Administrator);
 public Task<PolicyResult> ApplyAsync(ManagedApplication app)=>Task.Run(()=>IsElevated?ApplyNative(app):new(false,"Administrator privileges are required to install WFP rules.")); public Task<PolicyResult> RemoveAsync(ManagedApplication app)=>Task.Run(()=>IsElevated?RemoveNative(app):new(false,"Administrator privileges are required to remove WFP rules."));
 private PolicyResult ApplyNative(ManagedApplication app){try{if(app.DesiredPolicy==NetworkPolicy.Allowed){Native.Remove(app.FilterIds);app.FilterIds=[];return new(true,"WindTree block filters removed; Windows and other firewall policy now determine access.");}var ids=Native.Install(ApplicationIdentity.Normalize(app.Path),app.FilterIds); if(ids.Count!=4)return new(false,"WFP installed an incomplete policy.");app.FilterIds=ids;return new(true,"WFP filters are installed for IPv4/IPv6 inbound and outbound authorization.");}catch(Exception e){return new(false,e.Message);}} private PolicyResult RemoveNative(ManagedApplication app){try{Native.Remove(app.FilterIds);app.FilterIds=[];return new(true,"WindTree-owned filters removed.");}catch(Exception e){return new(false,e.Message);}}
