  public static List<ulong> Install(string path,IEnumerable<ulong> oldIds){Check(FwpmEngineOpen0(IntPtr.Zero,0,IntPtr.Zero,IntPtr.Zero,out var h));try{Check(FwpmTransactionBegin0(h,0));try{EnsureOwnership(h);foreach(var old in oldIds)DeleteOwned(h,old);Check(FwpmGetAppIdFromFileName0(path,out var app));try{var ids=Layers.Select(l=>Add(h,l,app,path)).ToList();Check(FwpmTransactionCommit0(h));return ids;}finally{FwpmFreeMemory0(ref app);}}catch{FwpmTransactionAbort0(h);throw;}}finally{FwpmEngineClose0(h);}}
